ALTER TABLE `appointments`
  ADD COLUMN `protocol` VARCHAR(32) NOT NULL DEFAULT '' AFTER `tenant_id`,
  ADD COLUMN `is_fit_in` BOOLEAN NOT NULL DEFAULT FALSE AFTER `reschedule_reason`,
  ADD COLUMN `fit_in_reason` VARCHAR(500) NULL AFTER `is_fit_in`;

ALTER TABLE `appointments` ADD UNIQUE INDEX `appointments_tenant_id_protocol_key` (`tenant_id`, `protocol`);

CREATE TABLE `appointment_history_entries` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`appointment_id` BIGINT UNSIGNED NOT NULL,`action` ENUM('CREATED', 'STATUS_CHANGED', 'RESCHEDULED') NOT NULL,`previous_status` ENUM('PENDING', 'CONFIRMED', 'IN_PROGRESS', 'COMPLETED', 'CANCELED', 'NO_SHOW') NULL,`new_status` ENUM('PENDING', 'CONFIRMED', 'IN_PROGRESS', 'COMPLETED', 'CANCELED', 'NO_SHOW') NULL,`previous_starts_at` DATETIME(3) NULL,`new_starts_at` DATETIME(3) NULL,`reason` VARCHAR(500) NULL,`is_fit_in` BOOLEAN NOT NULL DEFAULT FALSE,`user_id` BIGINT UNSIGNED NULL,`session_id` BIGINT UNSIGNED NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `appointment_history_entries_public_id_key` (`public_id`),INDEX `appointment_history_entries_tenant_appt_created_idx` (`tenant_id`,`appointment_id`,`created_at`),CONSTRAINT `appointment_history_entries_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `appointment_history_entries_appointment_id_fkey` FOREIGN KEY (`appointment_id`) REFERENCES `appointments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `appointment_history_entries_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `appointment_history_entries_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
